 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    # The framed template occupies the left block; the next all-zero column
    # separates it from the colored pattern bank.
    panel_w = next(c for c in range(1, w) if all(grid[r][c] == frame for r in range(h))) + 1
    right_start = panel_w + 1
    cuts = [r for r in range(h) if all(grid[r][c] == frame for c in range(panel_w))]
    out = [row[:panel_w] for row in grid]
    for a, b in zip(cuts, cuts[1:]):
        holes = {(r-a-1, c-1) for r in range(a+1, b) for c in range(1, panel_w-1) if grid[r][c] != frame}
        colors = {}
        for r in range(a+1, b):
            for c in range(right_start, w):
                v = grid[r][c]
                if v != 0 and v != frame:
                    colors.setdefault(v, set()).add((r-a-1, c-right_start))
        matched = next((color for color, shape in colors.items() if shape == holes), None)
        if matched is not None:
            for r, c in holes:
                out[a+1+r][1+c] = matched
    return out
