 "content": "def _shape(points):
    if not points:
        return None
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    return frozenset((r-r0, c-c0) for r, c in points)


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    # The template is enclosed by vertical frame-color rails.
    rails = [c for c in range(w) if all(grid[r][c] == frame for r in range(h))]
    panel_w = max(rails) + 1
    cuts = [r for r in range(h) if all(grid[r][c] == frame for c in range(panel_w))]
    out = [row[:panel_w] for row in grid]
    right_cols = range(panel_w, w)
    for top, bottom in zip(cuts, cuts[1:]):
        holes = {(r-top-1, c-1) for r in range(top+1, bottom)
                 for c in range(1, panel_w-1) if grid[r][c] != frame}
        target = _shape(holes)
        by_color = {}
        for r in range(top+1, bottom):
            for c in right_cols:
                value = grid[r][c]
                if value not in (0, frame):
                    by_color.setdefault(value, set()).add((r-top-1, c-panel_w))
        match = next((color for color, cells in by_color.items()
                      if _shape(cells) == target), None)
        if match is not None:
            for rr, cc in holes:
                out[top+1+rr][1+cc] = match
    return out
