    cuts = [r for r in range(h) if all(grid[r][c] == frame for c in range(panel_w))]

    # Each colored object on the right is a color-coded shape key.
    bank = {}
    for color in {grid[r][c] for r in range(h) for c in range(panel_w+1, w)} - {0, frame}:
